<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany;
class FeeDemand extends Model { protected $fillable=['university_id','college_id','admission_id','college_program_offering_id','academic_session_id','curriculum_id','billing_period_no','demand_no','currency','total_amount','mandatory_amount','enrollment_clearance_amount','paid_amount','adjusted_amount','outstanding_amount','status','generation_mode','demand_context','billing_basis_group','billing_period_label','bulk_run_key','generated_at','generated_by','cancelled_at','cancelled_by','cancellation_reason']; protected $casts=['billing_period_no'=>'integer','total_amount'=>'decimal:2','mandatory_amount'=>'decimal:2','enrollment_clearance_amount'=>'decimal:2','paid_amount'=>'decimal:2','adjusted_amount'=>'decimal:2','outstanding_amount'=>'decimal:2','generated_at'=>'datetime','cancelled_at'=>'datetime']; public function admission():BelongsTo{return $this->belongsTo(Admission::class);} public function items():HasMany{return $this->hasMany(FeeDemandItem::class)->orderBy('display_order')->orderBy('id');} }
